import {seed,age,assess,priority,decide,statusLabels,TODAY} from './domain.js';
const $=s=>document.querySelector(s);const money=n=>'₹'+n.toLocaleString('en-IN');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='arasu-demo-v1';let records;try{const v=JSON.parse(localStorage.getItem(KEY));records=Array.isArray(v)&&v.length===12&&v.every(a=>a.docs&&a.history&&statusLabels[a.status])?v:seed();}catch{records=seed();}
// Refresh built-in sample text while preserving saved decisions and officer-entered reasons.
const englishSamples=seed();
records=records.map(record=>{
 const sample=englishSamples.find(item=>item.id===record.id);
 return sample?{...record,name:sample.name,village:sample.village,occupation:sample.occupation,purpose:sample.purpose,docs:record.docs.map(doc=>({...doc,title:sample.docs.find(item=>item.key===doc.key)?.title||doc.title})),history:record.history.map(entry=>({...entry,officer:'A. Tamilselvi'}))}:record;
});
let view='pending',filter='all',query='',selected=records.find(a=>a.status==='pending')?.id||records[0].id,tab='overview',action='';
function persist(next){localStorage.setItem(KEY,JSON.stringify(next));records=next;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const icon={grid:'▦',files:'▤',history:'◷',help:'?',arrow:'↗',search:'⌕'};
function render(){if(sessionStorage.getItem('arasu-demo-session')!=='officer'){login();return;}const pending=records.filter(a=>a.status==='pending'),done=records.length-pending.length;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Arasu home"><span class="brand-icon">A</span><span>Arasu<small>Officer workspace</small></span></a><div class="office"><span class="office-icon">⌂</span><div>Revenue Department<small>Namakkal Taluk</small></div></div><div class="nav-label">Workspace</div><nav><button data-view="pending" class="${view==='pending'?'active':''}"><span>▦</span> Applications <b>${pending.length}</b></button><button data-view="history" class="${view==='history'?'active':''}"><span>◷</span> Decision history <b>${done}</b></button><button data-view="guide" class="${view==='guide'?'active':''}"><span>⊙</span> Review guide</button></nav><div class="sidebar-note"><span class="spark">✧</span><b>Technology assists.<br>You make the final decision.</b><p>Verify each recommendation before deciding.</p></div><div class="profile"><span class="avatar">T</span><div>A. Tamilselvi<small>Revenue Inspector · Demo</small><button id="logout" class="logout">Log out ↗</button></div></div></aside><main><header><div class="breadcrumb">Workspace <span>/</span> Income Certificate</div><div class="header-right"><span class="demo-dot"></span> Demo workspace <span class="date">28 October 2026</span></div></header><div class="page"><div class="title-row"><div class="title"><div class="eyebrow">REV–103 · Income Certificate</div><h1>${view==='history'?'Decision history':view==='guide'?'Review guide':'Every application, a step forward.'}</h1><p>Welcome, Tamilselvi. ${view==='pending'?'Start your day with a clear view of your work.':'Clear records to support your review.'}</p></div><button class="secondary" id="export">↓ Export records</button></div><div class="stats"><button data-filter="all" class="stat"><span>Pending review <span class="stat-icon">▤</span></span><strong>${pending.length}<small>Applications</small></strong><div class="stat-foot">Awaiting your decision</div></button><button data-filter="overdue" class="stat overdue"><span>Priority review <span class="stat-icon">◷</span></span><strong>${pending.filter(a=>age(a)>=15).length}<small>Applications</small></strong><div class="stat-foot"><i></i> 15 days or more</div></button><button data-filter="attention" class="stat"><span>Clarification needed <span class="stat-icon">⚑</span></span><strong>${pending.filter(a=>assess(a).issues.length).length}<small>Applications</small></strong><div class="stat-foot">Missing documents / conflicting information</div></button><button data-view="history" class="stat"><span>Completed <span class="stat-icon">✓</span></span><strong>${done}<small>/ ${records.length}</small></strong><div class="progress"><i style="width:${done/records.length*100}%"></i></div></button></div>${view==='guide'?guide():view==='history'?history():workspace()}</div><footer><span>Arasu · A simpler workspace for officers</span><span>Fictional data only · Unofficial demonstration</span></footer></main>`;bind();}
function workspace(){let list=records.filter(a=>a.status==='pending'&&(filter==='all'||filter==='overdue'&&age(a)>=15||filter==='attention'&&assess(a).issues.length||filter==='ready'&&!assess(a).issues.length)&&(a.name+' '+a.id+' '+a.village).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>age(b)-age(a));if(!list.some(a=>a.id===selected))selected=list[0]?.id;let a=records.find(a=>a.id===selected);return `<section class="workspace"><div class="queue"><div class="queue-head"><h2>Application queue <span>${list.length}</span></h2><span class="sort">Oldest first ↓</span></div><label class="search"><span>⌕</span><input id="search" value="${esc(query)}" placeholder="Name, reference or village…" aria-label="Search applications"><kbd>Search</kbd></label><div class="filters">${[['all','All'],['overdue','Priority'],['attention','Needs attention'],['ready','Ready']].map(([k,v])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${v}</button>`).join('')}</div><div class="application-list">${list.map(r=>`<button class="application ${selected===r.id?'chosen':''}" data-select="${r.id}"><div class="application-top"><span class="record-id">${r.id}</span><span class="age ${age(r)>=15?'late':''}">${age(r)} days</span></div><div class="applicant-line"><span class="person-avatar">${r.name.slice(0,1)}</span><div><h3>${r.name}</h3><p>${r.village} <span>·</span> ${r.members} members</p></div><span class="chevron">›</span></div><div class="application-bottom"><span class="badge ${age(r)>=15?'amber':assess(r).issues.length?'rose':'green'}">${age(r)>=15?'◷ Priority':assess(r).issues.length?'⚑ Needs attention':'✓ Ready for review'}</span><span>${money(r.income)} / year</span></div></button>`).join('')||'<div class="empty"><span>✓</span><h3>No applications</h3><p>Try another filter.</p></div>'}</div><div class="queue-footer">Demo date: 28 Oct 2026 · Priority after 15 days</div></div><div class="detail">${a?detail(a):'<div class="empty"><h2>All caught up</h2><p>There are no applications in this queue.</p></div>'}</div></section>`;}
function detail(a){const ai=assess(a);return `<div class="detail-head"><div><div class="record-id">${a.id}</div><h2>${a.name}</h2><p>${a.village} · Namakkal</p></div><span class="badge neutral">● Pending review</span></div><div class="tabs">${[['overview','Application details'],['documents',`Documents (${a.docs.filter(d=>d.present).length}/${a.docs.length})`],['timeline','Activity']].map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div><div class="detail-body">${tab==='overview'?`<div class="info-grid"><div><label>Annual income</label><strong>${money(a.income)}</strong></div><div><label>Submitted on</label><strong>${a.submitted.split('-').reverse().join('.')}</strong></div><div><label>Occupation</label><b>${a.occupation}</b></div><div><label>Purpose</label><b>${a.purpose}</b></div></div><div class="assistant"><div class="assistant-heading"><span class="ai-icon">✧</span><h3>AI review assistance</h3><span class="ai-label">Rule-based demo</span></div><p class="summary">${a.name} from ${a.village} has declared an annual household income of ${money(a.income)} for ${a.members} family members. The certificate is requested for ${a.purpose.toLowerCase()}.</p><div class="check-heading">Review findings</div>${ai.issues.length?ai.issues.map(s=>`<div class="finding warning"><span>!</span><p>${s}</p></div>`).join(''):'<div class="finding success"><span>✓</span><p>All sample documents are present. The income figures match.</p></div>'}<div class="recommendation"><span>Recommendation</span><strong>${ai.suggestion==='returned'?'Return for clarification':'Consider for approval'} ↗</strong><p>${ai.suggestion==='returned'?'Review again after the issues have been clarified.':'Verify the authenticity of the original documents in person.'}</p></div><div class="ai-disclaimer">ⓘ Assistance based on sample data only. The officer makes the final decision.</div></div><button class="text-button" data-tab="documents">View supporting documents →</button>`:tab==='documents'?`<div class="section-intro"><h3>Attached documents</h3><p>These are fictional text samples for demonstration.</p></div>${a.docs.map(d=>`<div class="doc-row"><span class="doc-icon">▤</span><div><b>${d.title}</b><small>${d.present?'Text sample · Fictional data':'Not attached'}</small></div>${d.present?`<button class="secondary" data-doc="${d.key}">View ↗</button>`:'<span class="badge rose">Missing</span>'}</div>`).join('')}`:`<div class="timeline"><span class="timeline-dot"></span><b>Application received</b><p>${a.submitted} · Demo e-Sevai submission</p><p>Assigned for officer review.</p></div><div class="timeline"><span class="timeline-dot pale"></span><b>Document review pending</b><p>Automated assistance does not record decisions.</p></div>`}</div><div class="decision-bar"><div><b>Your review. Your decision.</b><small>A reason is required.</small></div><div class="decision-buttons"><button class="reject" data-action="rejected">Reject</button><button class="secondary" data-action="returned">Return</button><button class="primary" data-action="approved">✓ Approve</button></div></div>`;}
function history(){const all=records.filter(a=>a.status!=='pending');return `<section class="history-panel"><div class="panel-heading"><h2>Recorded decisions</h2><button class="secondary" id="reset">Reset demo</button></div><p>Demo records are saved only in this browser.</p>${all.map(a=>{let h=a.history.at(-1);return `<article class="history-item"><div><span class="record-id">${a.id}</span><h3>${a.name}</h3><p>${esc(h.reason)}</p><small>${h.officer} · ${new Date(h.at).toLocaleString('en-IN')}</small></div><span class="badge ${a.status==='approved'?'green':a.status==='returned'?'amber':'rose'}">${statusLabels[a.status]}</span></article>`;}).join('')||'<div class="empty"><span>◷</span><h3>No decisions yet</h3><p>Review an application to record your first decision.</p></div>'}</section>`;}
function guide(){return `<section class="guide"><div class="eyebrow">Transparent review</div><h2>A simple process with human oversight</h2><ol><li><b>Understand priority</b><p>Applications waiting 15 days or more appear first. This is a demo queue rule, not a statutory deadline.</p></li><li><b>Review documents</b><p>Inspect the sample photo, address proof, family card, self-declaration and income evidence. Officers must separately verify additional occupation-specific documents.</p></li><li><b>Evaluate the assistance</b><p>Rules detect only missing documents and differences between income figures. There is no OCR or live AI connection. This does not determine fraud or legal eligibility.</p></li><li><b>Decide with a reason</b><p>Approval, rejection or return: every decision requires a reason and officer confirmation. An issue alone does not automatically justify rejection.</p></li></ol><a href="https://tnesevai.tn.gov.in/Pages/FAQ.aspx" target="_blank" rel="noreferrer">Official e-Sevai document guide ↗</a><p>This is an independent demonstration without government-system integration.</p></section>`;}
function bind(){$('#logout').onclick=()=>{sessionStorage.removeItem('arasu-demo-session');render();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{view='pending';filter=b.dataset.filter;render();});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;tab='overview';render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$('#search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>openDecision(b.dataset.action));document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>openDoc(b.dataset.doc));$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({demo:true,referenceDate:TODAY,applications:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='arasu-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo records exported.');};$('#reset')?.addEventListener('click',()=>{if(confirm('Clear all demo decisions and reset?')){try{persist(seed());view='pending';selected=records[0].id;render();toast('Demo reset.');}catch{toast('Unable to save. Please allow browser storage.');}}});}
function openDecision(s){action=s;$('#decision-form').reset();$('#decision-title').textContent={approved:'Approve this application?',returned:'Return this application?',rejected:'Reject this application?'}[s];$('#decision-description').textContent=`${records.find(a=>a.id===selected).name} · ${selected}. The decision will be saved in this browser's demo history.`;$('#decision').showModal();}
$('#cancel-decision').onclick=()=>$('#decision').close();$('#decision-form').onsubmit=e=>{e.preventDefault();try{let a=records.find(a=>a.id===selected);persist(records.map(r=>r.id===selected?decide(a,action,$('#reason').value,$('#verified').checked):r));$('#decision').close();render();toast('Decision and reason recorded.');}catch(err){toast(err.message);}};
function openDoc(key){const a=records.find(a=>a.id===selected),d=a.docs.find(d=>d.key===key);$('#document-content').innerHTML=`<div class="eyebrow">Fictional document · ${a.id}</div><h2>${d.title}</h2><div class="sample-document"><div class="watermark">DEMO / SAMPLE</div><h3>${a.name}</h3><p>Village: ${a.village}</p><p>${key==='income'?`Annual income: ${money(a.evidenceIncome)}`:key==='family'?`Family members: ${a.members}`:key==='declaration'?`Declared annual income: ${money(a.income)}`:key==='address'?'Address: Sample Street, '+a.village+', Namakkal':'Sample photo placeholder'}</p><p>Date: ${a.submitted}</p><hr><p>Text created for demonstration. This is not a verified government document.</p></div>`;$('#document').showModal();}$('#close-document').onclick=()=>$('#document').close();
function login(){$('#app').innerHTML=`<div class="login-page"><div class="login-story"><a class="brand" href="#"><span class="brand-icon">A</span><span>Arasu<small>Officer workspace</small></span></a><div><div class="eyebrow">REV–103 · Income Certificate</div><h1>Clear reviews.<br>Confident decisions.</h1><p>A simple workspace to review applications carefully<br>and record decisions with clear reasons.</p><div class="login-features"><span>01 · Priority queue</span><span>02 · Document review assistance</span><span>03 · Officer's final decision</span></div></div><small>Fictional data only · Unofficial demonstration</small></div><div class="login-form-wrap"><form id="login-form"><div class="eyebrow">Namakkal · Revenue Department</div><h2>Welcome, officer.</h2><p>Sign in to the demo workspace.</p><label for="email">Email</label><input id="email" type="email" autocomplete="username" required value="officer@arasu.demo"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required value="Demo@123"><p id="login-error" role="alert"></p><button class="primary" type="submit">Enter workspace →</button></form></div></div>`;$('#login-form').onsubmit=e=>{e.preventDefault();if($('#email').value.trim()==='officer@arasu.demo'&&$('#password').value==='Demo@123'){sessionStorage.setItem('arasu-demo-session','officer');render();}else{$('#login-error').textContent='Incorrect email or password.';}};}
render();
